	t.Parallel()

	prefixes := []string{"entire ", `go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go `}

	if !IsManagedHookCommand("entire hooks codex stop", prefixes) {
		t.Fatal("expected direct entire command to match")
